    public List<Message> apply(Message message) {
        List<Message> messages = new ArrayList<>();
        messages.add(message);

        if (message.getStatus() == MessageStatus.SENT) {
            Message copy = new Message(
                message.getChannel(),
                ARCHIVE_EMAIL,
                "[Cópia] " + message.getSubject(),
                message.getBody(),
                MessageStatus.SENT
            );
            messages.add(copy);
        }

        return messages;
    }
}

