package com.pousadamarealta;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import io.javalin.Javalin;
import io.javalin.testtools.JavalinTest;
import org.junit.jupiter.api.*;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
public class ReservationSystemIT {

    private static Process postgresProcess;
    private static final String DB_URL = "jdbc:postgresql://localhost:5432/test_pousada";
    private static final String DB_USER = "postgres";
    private static final String DB_PASSWORD = "postgres";

    @BeforeAll
    static void setupDatabase() throws Exception {
        System.setProperty("DB_URL", DB_URL);
        System.setProperty("DB_USER", DB_USER);
        System.setProperty("DB_PASSWORD", DB_PASSWORD);
        System.setProperty("PORT", "7071");
    }

    @Test
    @Order(1)
    public void testGetRooms() {
        String[] args = {};
        Application.main(args);

        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create("http://localhost:7071/rooms"))
            .GET()
            .build();

        try {
            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
            assertThat(response.statusCode()).isEqualTo(200);
            assertThat(response.body()).contains("101", "102", "201", "202", "301");
            assertThat(response.body()).contains("STANDARD", "DELUXE", "SUITE");
        } catch (Exception e) {
            Assertions.fail("Request failed: " + e.getMessage());
        }
    }

    @Test
    public void testCreateAndConfirmReservation() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(new JavaTimeModule());

        Map<String, Object> createRequest = Map.of(
            "roomNumber", "101",
            "guestName", "João Silva",
            "guestEmail", "joao@example.com",
            "guestCpf", "12345678901",
            "checkIn", "2027-03-10",
            "checkOut", "2027-03-12",
            "guests", 2,
            "ratePlan", "STANDARD"
        );

        String requestBody = mapper.writeValueAsString(createRequest);

        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create("http://localhost:7071/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(requestBody))
            .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        assertThat(response.statusCode()).isEqualTo(201);

        Map<String, Object> reservation = mapper.readValue(response.body(), Map.class);
        assertThat(reservation.get("status")).isEqualTo("PENDING");
        assertThat(reservation.get("nights")).isEqualTo(2);

        Integer reservationId = (Integer) reservation.get("id");

        HttpRequest confirmRequest = HttpRequest.newBuilder()
            .uri(URI.create("http://localhost:7071/reservations/" + reservationId + "/confirmation"))
            .POST(HttpRequest.BodyPublishers.noBody())
            .build();

        HttpResponse<String> confirmResponse = client.send(confirmRequest, HttpResponse.BodyHandlers.ofString());
        assertThat(confirmResponse.statusCode()).isEqualTo(200);

        Map<String, Object> confirmedReservation = mapper.readValue(confirmResponse.body(), Map.class);
        assertThat(confirmedReservation.get("status")).isEqualTo("CONFIRMED");
        assertThat(confirmedReservation.get("amountPaid")).isNotNull();
    }

    @Test
    public void testEmailValidation() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(new JavaTimeModule());

        Map<String, Object> createRequest = Map.of(
            "roomNumber", "102",
            "guestName", "Maria Costa",
            "guestEmail", "maria.example.com",
            "guestCpf", "98765432109",
            "checkIn", "2027-04-10",
            "checkOut", "2027-04-12",
            "guests", 1,
            "ratePlan", "STANDARD"
        );

        String requestBody = mapper.writeValueAsString(createRequest);

        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create("http://localhost:7071/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(requestBody))
            .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        assertThat(response.statusCode()).isEqualTo(201);

        Map<String, Object> reservation = mapper.readValue(response.body(), Map.class);
        Integer reservationId = (Integer) reservation.get("id");

        HttpRequest confirmRequest = HttpRequest.newBuilder()
            .uri(URI.create("http://localhost:7071/reservations/" + reservationId + "/confirmation"))
            .POST(HttpRequest.BodyPublishers.noBody())
            .build();

        client.send(confirmRequest, HttpResponse.BodyHandlers.ofString());

        HttpRequest messagesRequest = HttpRequest.newBuilder()
            .uri(URI.create("http://localhost:7071/messages"))
            .GET()
            .build();

        HttpResponse<String> messagesResponse = client.send(messagesRequest, HttpResponse.BodyHandlers.ofString());
        String messagesBody = messagesResponse.body();

        assertThat(messagesBody).contains("BLOCKED");
        assertThat(messagesBody).contains("maria.example.com");
    }

    @Test
    public void testHighSeasonPricing() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(new JavaTimeModule());

        Map<String, Object> createRequest = Map.of(
            "roomNumber", "201",
            "guestName", "Carlos Dias",
            "guestEmail", "carlos@example.com",
            "guestCpf", "11122233344",
            "checkIn", "2027-07-10",
            "checkOut", "2027-07-12",
            "guests", 2,
            "ratePlan", "STANDARD"
        );

        String requestBody = mapper.writeValueAsString(createRequest);

        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create("http://localhost:7071/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(requestBody))
            .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        Map<String, Object> reservation = mapper.readValue(response.body(), Map.class);

        double subtotal = (Double) reservation.get("subtotal");
        assertThat(subtotal).isEqualTo(599.76);
    }

    @Test
    public void testNonRefundablePlan() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(new JavaTimeModule());

        Map<String, Object> createRequest = Map.of(
            "roomNumber", "202",
            "guestName", "Ana Paula",
            "guestEmail", "ana@example.com",
            "guestCpf", "55566677788",
            "checkIn", "2027-05-10",
            "checkOut", "2027-05-12",
            "guests", 2,
            "ratePlan", "NON_REFUNDABLE"
        );

        String requestBody = mapper.writeValueAsString(createRequest);

        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create("http://localhost:7071/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(requestBody))
            .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        Map<String, Object> reservation = mapper.readValue(response.body(), Map.class);

